import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { spawn } from 'node:child_process';

const root = process.cwd();
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const server = createServer(async (req, res) => {
  try {
    const file = resolve(root, '.' + req.url);
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('nf');
  }
});
server.listen(52601, '127.0.0.1', () => {
  const cp = spawn('C:/Users/lokta/AppData/Local/ms-playwright/chromium-1200/chrome-win64/chrome.exe', [
    '--headless',
    '--no-sandbox',
    '--disable-gpu',
    '--enable-logging=stderr',
    '--dump-dom',
    'http://127.0.0.1:52601/demo.html',
  ]);
  let out = '';
  let err = '';
  cp.stdout.on('data', (d) => (out += d));
  cp.stderr.on('data', (d) => (err += d));
  cp.on('close', (code) => {
    console.error('EXIT ' + code + ' OUT_LEN ' + out.length);
    const i = out.indexOf('id="board-1"');
    console.error('BOARD1_AT ' + i);
    console.error('SLICE ' + JSON.stringify(out.slice(i, i + 500)));
    console.error(
      'CONSOLE ' +
        JSON.stringify(
          err
            .split('\n')
            .filter((l) => /CONSOLE|Uncaught|ERROR/.test(l))
            .slice(0, 15),
        ),
    );
    server.close();
  });
});

