import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { spawn } from 'node:child_process';
import { writeFile } from 'node:fs/promises';

const root = resolve(process.cwd());
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const server = createServer(async (req, res) => {
  try {
    const file = resolve(root, '.' + req.url);
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const url = 'http://127.0.0.1:' + server.address().port + '/demo.html';
const chrome = 'C:/Users/lokta/AppData/Local/ms-playwright/chromium-1200/chrome-win64/chrome.exe';
const run = (args) =>
  new Promise((res2) => {
    const cp = spawn(chrome, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    cp.stdout.on('data', (d) => (out += d));
    cp.stderr.on('data', (d) => (err += d));
    const kill = setTimeout(() => cp.kill(), 30000);
    cp.on('close', (code) => {
      clearTimeout(kill);
      res2({ code, out, err });
    });
  });
const r = await run(['--headless', '--no-sandbox', '--disable-gpu', '--enable-logging=stderr', '--dump-dom', url]);
const count = (s, re) => (s.match(re) || []).length;
console.error('OUT_LEN ' + r.out.length);
console.error('SQUARE_COUNT ' + count(r.out, /<square[\s>]/g));
console.error('PIECE_COUNT ' + count(r.out, /<piece[\s>]/g));
console.error('SHAPE_SVG ' + count(r.out, /<svg[^>]*cg-shapes/g));
console.error('SHAPE_PATH ' + count(r.out, /<path[\s>]/g));
// show the first 400 chars of board-1 content
const i = r.out.indexOf('id="board-1"');
console.error('BOARD1_AT ' + i);
console.error('SLICE ' + JSON.stringify(r.out.slice(i, i + 600)));
console.error('HAS_CG_SQUARE_CLASS ' + /class="[^"]*square-/.test(r.out));
console.error('CONSOLE ' + JSON.stringify(r.err.split('\n').filter((l) => /CONSOLE|Uncaught|ERROR/.test(l)).slice(0, 15)));
await writeFile('C:/Users/lokta/AppData/Local/Temp/cg-dump.html', r.out);
server.close();

