// Temporary smoke check: serve the repo over HTTP, load demo.html in headless
// chromium, assert every board rendered, save a screenshot.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { spawn } from 'node:child_process';

const root = process.argv[2];
const chrome = process.argv[3];
const shotPath = process.argv[4];
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json' };

const server = createServer(async (req, res) => {
  try {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p === '/') p = '/demo.html';
    const file = resolve(root, '.' + p);
    if (!file.startsWith(root)) { res.writeHead(403); res.end(); return; }
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const url = 'http://127.0.0.1:' + server.address().port + '/demo.html';

const run = (args) =>
  new Promise((res2) => {
    const cp = spawn(chrome, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    cp.stdout.on('data', (d) => (out += d));
    cp.stderr.on('data', (d) => (err += d));
    const kill = setTimeout(() => cp.kill(), 30000);
    cp.on('close', (code) => {
      clearTimeout(kill);
      res2({ code, out, err });
    });
  });

const base = ['--headless', '--no-sandbox', '--disable-gpu', '--virtual-time-budget=4000'];
const domRun = await run([...base, '--enable-logging=stderr', '--dump-dom', url]);
const shotRun = await run([...base, '--window-size=1500,950', '--screenshot=' + shotPath, url]);
server.close();

const count = (s, re) => (s.match(re) || []).length;
const sliceBoard = (s, id) => {
  const start = s.indexOf('id="' + id + '"');
  const rest = s.slice(start);
  const m = rest.slice(1).search(/id="board-\d+|<\/body>/);
  return m === -1 ? rest : rest.slice(0, m + 1);
};
const boards = {};
for (const id of ['board-1', 'board-2', 'board-3', 'board-4', 'board-5']) {
  const b = sliceBoard(domRun.out, id);
  boards[id] = {
    squares: count(b, /<square[\s>]/g),
    pieces: count(b, /<piece[\s>]/g),
  };
}
const shapeSvgs = domRun.out.match(/<svg class="cg-shapes"[\s\S]*?<\/svg>/g) || [];
const shapePaths = shapeSvgs.reduce((n, svg) => n + count(svg, /<path[\s>]/g), 0);
const consoleErrors = domRun.err
  .split('\n')
  .filter((l) => /CONSOLE.*(error|Uncaught)|Uncaught/.test(l));

const expected = { 'board-1': 32, 'board-2': 19, 'board-3': 32, 'board-4': 32, 'board-5': 32 };
const failures = [];
if (domRun.code !== 0) failures.push('dump-dom exited ' + domRun.code);
if (shapeSvgs.length !== 1) failures.push('expected 1 cg-shapes svg, got ' + shapeSvgs.length);
if (shapePaths !== 7) failures.push('expected 7 shape paths, got ' + shapePaths);
for (const [id, pieces] of Object.entries(expected)) {
  if (boards[id].squares !== 64) failures.push(id + ': expected 64 squares, got ' + boards[id].squares);
  if (boards[id].pieces !== pieces) failures.push(id + ': expected ' + pieces + ' pieces, got ' + boards[id].pieces);
}
if (consoleErrors.length) failures.push('console errors: ' + JSON.stringify(consoleErrors));
if (shotRun.code !== 0) failures.push('screenshot run exited ' + shotRun.code);

console.log(JSON.stringify({ url, boards, shapeSvgs: shapeSvgs.length, shapePaths, consoleErrors, failures }, null, 2));
process.exit(failures.length ? 1 : 0);

