// Temporary smoke check: serve the repo over HTTP, load demo.html in headless
// chromium, assert every board rendered, save a screenshot.
//
// Expected values derived from demo.html configs and the current render
// architecture (board tiles are an embedded SVG background on <cg-board>;
// <square> elements only exist for highlights; each board carries one
// <piece class="ghost"> drag ghost):
//   board-1: default start FEN -> 32 pieces
//   board-2: FEN r2q2k1/1p6/p2p4/2pN1rp1/N1Pb2Q1/8/PP1B4/R6K -> 19 pieces
//   board-3: default start FEN -> 32 pieces, 6 autoShapes -> 6 <path> + 6 <text>
//   board-4/5: default start FEN -> 32 pieces, on-square <coords>
import { createServer } from 'node:http';
import { readFile, writeFile } from 'node:fs/promises';
import { resolve, extname } from 'node:path';
import { spawn } from 'node:child_process';

const root = resolve(process.argv[2]);
const chrome = process.argv[3];
const shotPath = process.argv[4];
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json' };

const server = createServer(async (req, res) => {
  try {
    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
    if (p === '/') p = '/demo.html';
    const file = resolve(root, '.' + p);
    if (!file.startsWith(root)) { res.writeHead(403); res.end(); return; }
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': types[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('not found');
  }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const url = 'http://127.0.0.1:' + server.address().port + '/demo.html';

const run = (args) =>
  new Promise((res2) => {
    const cp = spawn(chrome, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    cp.stdout.on('data', (d) => (out += d));
    cp.stderr.on('data', (d) => (err += d));
    const kill = setTimeout(() => cp.kill(), 30000);
    cp.on('close', (code) => {
      clearTimeout(kill);
      res2({ code, out, err });
    });
  });

const base = ['--headless', '--no-sandbox', '--disable-gpu'];
const domRun = await run([...base, '--enable-logging=stderr', '--dump-dom', url]);
const shotRun = await run([...base, '--window-size=1500,950', '--screenshot=' + shotPath, url]);
server.close();

const count = (s, re) => (s.match(re) || []).length;
const sliceBoard = (s, n) => {
  const start = s.indexOf('id="board-' + n + '"');
  if (start === -1) return '';
  const rest = s.slice(start);
  const m = rest.slice(1).search(/id="board-\d+|<\/body>/);
  return m === -1 ? rest : rest.slice(0, m + 1);
};
const realPieces = (b) => count(b, /<piece class="(?:white|black) /g);
const ghosts = (b) => count(b, /<piece class="ghost"/g);

const dom = domRun.out;
const expectedPieces = { 'board-1': 32, 'board-2': 19, 'board-3': 32, 'board-4': 32, 'board-5': 32 };
const failures = [];
if (count(dom, /<cg-board/g) !== 5) failures.push('expected 5 cg-board, got ' + count(dom, /<cg-board/g));
const boards = {};
for (const [n, exp] of Object.entries(expectedPieces)) {
  const b = sliceBoard(dom, n.slice(6));
  const rp = realPieces(b);
  const g = ghosts(b);
  boards[n] = { pieces: rp, ghosts: g };
  if (!b) failures.push(n + ': not found in DOM');
  if (rp !== exp) failures.push(n + ': expected ' + exp + ' pieces, got ' + rp);
  if (g !== 1) failures.push(n + ': expected 1 ghost piece, got ' + g);
}
const b3 = sliceBoard(dom, '3');
if (count(b3, /<path[\s>]/g) !== 6) failures.push('board-3: expected 6 shape paths, got ' + count(b3, /<path[\s>]/g));
if (count(b3, /<text[\s>]/g) !== 6) failures.push('board-3: expected 6 shape labels, got ' + count(b3, /<text[\s>]/g));
if (count(sliceBoard(dom, '4'), /<coords class="squares/g) !== 8)
  failures.push('board-4: expected 8 on-square coord rows');
if (count(sliceBoard(dom, '5'), /<coords class="squares/g) !== 8)
  failures.push('board-5: expected 8 on-square coord rows');
const consoleErrors = domRun.err
  .split('\n')
  .filter((l) => /CONSOLE.*\berror\b|Uncaught/.test(l))
  .map((l) => l.replace(/^.*CONSOLE\(\d+\/\d+\)\[?/, '').slice(0, 200));
if (consoleErrors.length) failures.push('console errors: ' + consoleErrors.join(' | '));
if (shotRun.code !== 0) failures.push('screenshot run exited ' + shotRun.code);

console.log(JSON.stringify({ url, boards, consoleErrors, failures }, null, 2));
process.exit(failures.length ? 1 : 0);

